// Bugünün takvim etkinliklerinden Telegram metni ve HTML mail gövdesi hazırlar.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

const etkinlikler = $input
  .all()
  .map((x) => x.json)
  .filter((e) => e && e.start && (e.start.dateTime || e.start.date) && e.status !== 'cancelled')
  .sort((a, b) => new Date(a.start.dateTime || a.start.date) - new Date(b.start.dateTime || b.start.date));

const bugun = new Date().toLocaleDateString('tr-TR', { weekday: 'long', day: 'numeric', month: 'long' });
const ss = (d) => d.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' });
const saatAraligi = (e) => {
  if (e.start.date) return 'Tüm gün';
  const bas = new Date(e.start.dateTime);
  const bit = e.end && e.end.dateTime ? new Date(e.end.dateTime) : null;
  return ss(bas) + (bit ? '–' + ss(bit) : '');
};
const yer = (e) => String(e.location || '').split('\n')[0].trim();

const text = etkinlikler.length
  ? '📅 ' + bugun + ' — ' + etkinlikler.length + ' etkinlik\n\n' +
    etkinlikler
      .map((e) => {
        const yeri = yer(e);
        const gorusme = e.hangoutLink ? '\n  🎥 ' + e.hangoutLink : '';
        return '• ' + saatAraligi(e) + '  ' + (e.summary || '(başlıksız)') + (yeri ? '\n  📍 ' + yeri : '') + gorusme;
      })
      .join('\n')
  : '📅 ' + bugun + '\nBugün takviminizde etkinlik yok. 🎉';

const html = etkinlikler.length
  ? [
      '<div style="font-family:sans-serif;max-width:640px">',
      '<h2>📅 ' + esc(bugun) + '</h2>',
      '<ul style="padding-left:20px">',
      etkinlikler
        .map((e) => {
          const yeri = yer(e);
          const baslik = e.htmlLink
            ? '<a href="' + esc(e.htmlLink) + '">' + esc(e.summary || '(başlıksız)') + '</a>'
            : esc(e.summary || '(başlıksız)');
          return '<li style="margin:6px 0"><b>' + esc(saatAraligi(e)) + '</b> — ' + baslik +
            (yeri ? ' <span style="color:#555">· ' + esc(yeri) + '</span>' : '') +
            (e.hangoutLink ? ' <a href="' + esc(e.hangoutLink) + '">🎥</a>' : '') + '</li>';
        })
        .join(''),
      '</ul></div>',
    ].join('')
  : '';

return [{
  json: {
    adet: etkinlikler.length,
    gonderilecek: etkinlikler.length > 0,
    konu: '[n8n] 📅 ' + bugun + ': ' + etkinlikler.length + ' etkinlik',
    text,
    html,
  },
}];

// Telegram kuruluysa özet oraya gider; etkinlik yoksa hiç mesaj gönderilmez.
const j = $input.first().json;
if (!j.gonderilecek) return [];
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE özet mail olarak gider (çift bildirim olmasın).
const j = $input.first().json;
if (!j.gonderilecek) return [];
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];
